// Deploy bootstrap: load chunked B64 parts, gunzip self-contained source, dynamic-import.
const parts = await Promise.all([
  Deno.readTextFile(new URL("./b64/0.txt", import.meta.url)),
  Deno.readTextFile(new URL("./b64/1.txt", import.meta.url)),
  Deno.readTextFile(new URL("./b64/2.txt", import.meta.url)),
  Deno.readTextFile(new URL("./b64/3.txt", import.meta.url))
]);
const B64 = parts.join("");

function b64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function gunzip(bytes: Uint8Array): Promise<string> {
  const ds = new DecompressionStream("gzip");
  const stream = new Blob([bytes]).stream().pipeThrough(ds);
  const ab = await new Response(stream).arrayBuffer();
  return new TextDecoder().decode(ab);
}

const source = await gunzip(b64ToBytes(B64));
await import("data:application/typescript;charset=utf-8," + encodeURIComponent(source));
